// ---------- shared: util.ts ----------
// Shared server helpers for the Sentence Factory Edge Functions.
import { createClient, type SupabaseClient } from 'npm:@supabase/supabase-js@2';

const BUCKET = 'submissions';

// ---------------------------------------------------------------- CORS
function corsHeaders(req: Request): Record<string, string> {
  const allowed = (Deno.env.get('ALLOWED_ORIGINS') ?? '')
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean);
  const origin = req.headers.get('origin') ?? '';
  const allowOrigin = allowed.length === 0 ? '*' : allowed.includes(origin) ? origin : allowed[0];
  return {
    'Access-Control-Allow-Origin': allowOrigin,
    'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type, x-teacher-token',
    'Access-Control-Allow-Methods': 'POST, GET, OPTIONS',
    Vary: 'Origin',
  };
}

function json(req: Request, body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders(req), 'Content-Type': 'application/json', 'Cache-Control': 'no-store' },
  });
}

class HttpError extends Error {
  constructor(public status: number, message: string) {
    super(message);
  }
}

function serve(handler: (req: Request) => Promise<Response>) {
  Deno.serve(async (req) => {
    if (req.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders(req) });
    try {
      return await handler(req);
    } catch (e) {
      if (e instanceof HttpError) return json(req, { error: e.message }, e.status);
      console.error(e);
      return json(req, { error: 'Something went wrong on the server. Please try again.' }, 500);
    }
  });
}

// ---------------------------------------------------------------- Supabase admin client (server only)
let _admin: SupabaseClient | null = null;
function admin(): SupabaseClient {
  if (!_admin) {
    const url = Deno.env.get('SUPABASE_URL');
    const key = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY');
    if (!url || !key) throw new HttpError(500, 'Server is missing Supabase configuration.');
    _admin = createClient(url, key, { auth: { persistSession: false, autoRefreshToken: false } });
  }
  return _admin;
}

function must<T>(res: { data: T; error: { message: string } | null }): T {
  if (res.error) {
    console.error(res.error);
    throw new HttpError(500, 'Database error. Please try again.');
  }
  return res.data;
}

// ---------------------------------------------------------------- Encoding / crypto
const enc = new TextEncoder();

function b64url(bytes: Uint8Array): string {
  let bin = '';
  for (const b of bytes) bin += String.fromCharCode(b);
  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}
function fromB64url(s: string): Uint8Array<ArrayBuffer> {
  const b = atob(s.replace(/-/g, '+').replace(/_/g, '/') + '==='.slice((s.length + 3) % 4));
  return Uint8Array.from(b, (c) => c.charCodeAt(0));
}

function randomToken(bytes = 24): string {
  return b64url(crypto.getRandomValues(new Uint8Array(bytes)));
}

function safeEqual(a: string, b: string): boolean {
  const x = enc.encode(a);
  const y = enc.encode(b);
  let diff = x.length ^ y.length;
  for (let i = 0; i < Math.max(x.length, y.length); i++) diff |= (x[i] ?? 0) ^ (y[i] ?? 0);
  return diff === 0;
}

async function hmac(secret: string, data: string): Promise<string> {
  const key = await crypto.subtle.importKey('raw', enc.encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, [
    'sign',
  ]);
  return b64url(new Uint8Array(await crypto.subtle.sign('HMAC', key, enc.encode(data))));
}

async function sha256(s: string): Promise<string> {
  return b64url(new Uint8Array(await crypto.subtle.digest('SHA-256', enc.encode(s))));
}

// ---------------------------------------------------------------- PIN hashing (PBKDF2-SHA256)
const PBKDF2_ITER = 150_000;

async function pbkdf2(pin: string, salt: Uint8Array<ArrayBuffer>, iter: number): Promise<Uint8Array> {
  const key = await crypto.subtle.importKey('raw', enc.encode(pin), 'PBKDF2', false, ['deriveBits']);
  const bits = await crypto.subtle.deriveBits({ name: 'PBKDF2', hash: 'SHA-256', salt, iterations: iter }, key, 256);
  return new Uint8Array(bits);
}

async function hashPin(pin: string): Promise<string> {
  const salt = crypto.getRandomValues(new Uint8Array(16));
  const h = await pbkdf2(pin, salt, PBKDF2_ITER);
  return `pbkdf2$${PBKDF2_ITER}$${b64url(salt)}$${b64url(h)}`;
}

async function verifyPin(pin: string, stored: string): Promise<boolean> {
  const [alg, iter, salt, hash] = stored.split('$');
  if (alg !== 'pbkdf2' || !iter || !salt || !hash) return false;
  const h = await pbkdf2(pin, fromB64url(salt), Number(iter));
  return safeEqual(b64url(h), hash);
}

const PIN_RE = /^\d{4,8}$/;

// ---------------------------------------------------------------- Teacher session tokens (HMAC signed)
function sessionSecret(): string {
  const s = Deno.env.get('TEACHER_SESSION_SECRET') ?? '';
  if (s.length < 24 || s.startsWith('CHANGE-ME')) {
    throw new HttpError(500, 'TEACHER_SESSION_SECRET is not configured on the server.');
  }
  return s;
}

interface SessionPayload {
  sub: string; // teacher id
  exp: number; // unix seconds
  pv: string; // fingerprint of the PIN hash — changing the PIN signs everyone out
}

async function signSession(p: SessionPayload): Promise<string> {
  const body = b64url(enc.encode(JSON.stringify(p)));
  return `${body}.${await hmac(sessionSecret(), body)}`;
}

async function readSession(token: string | null): Promise<SessionPayload | null> {
  if (!token) return null;
  const [body, sig] = token.split('.');
  if (!body || !sig) return null;
  if (!safeEqual(sig, await hmac(sessionSecret(), body))) return null;
  try {
    const p = JSON.parse(new TextDecoder().decode(fromB64url(body))) as SessionPayload;
    if (typeof p.sub !== 'string' || !p.sub || typeof p.exp !== 'number' || p.exp < Date.now() / 1000) return null;
    return p;
  } catch {
    return null;
  }
}

async function pinFingerprint(pinHash: string | null): Promise<string> {
  return (await sha256(pinHash ?? 'initial-pin')).slice(0, 12);
}

// ---------------------------------------------------------------- Misc
function clientIp(req: Request): string {
  return (
    req.headers.get('x-forwarded-for')?.split(',')[0].trim() ||
    req.headers.get('cf-connecting-ip') ||
    req.headers.get('x-real-ip') ||
    'unknown'
  );
}

function str(v: unknown, max = 200): string {
  return typeof v === 'string' ? v.replace(/[<>]/g, '').replace(/\s+/g, ' ').trim().slice(0, max) : '';
}

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

interface TeacherRow {
  id: string;
  title: string;
  name: string;
  school: string | null;
  subject: string | null;
  welcome_message: string | null;
  photo_path: string | null;
  pin_hash: string | null;
  is_admin: boolean;
  photo_required: boolean;
  word_of_day: unknown;
  challenge: unknown;
  created_at: string;
}

const displayName = (t: { title: string; name: string }) => `${t.title} ${t.name}`.trim();

/** Short-lived signed URLs for a set of storage paths (missing paths are skipped). */
async function signUrls(paths: (string | null | undefined)[], seconds = 3600): Promise<Map<string, string>> {
  const list = [...new Set(paths.filter((p): p is string => !!p))];
  const map = new Map<string, string>();
  if (!list.length) return map;
  const { data, error } = await admin().storage.from(BUCKET).createSignedUrls(list, seconds);
  if (error) console.error(error);
  for (const d of data ?? []) if (d.path && d.signedUrl) map.set(d.path, d.signedUrl);
  return map;
}

/** Public-safe view of a teacher (never includes the PIN hash). */
function publicTeacher(t: TeacherRow, urls: Map<string, string>) {
  return {
    id: t.id,
    title: t.title,
    name: t.name,
    display_name: displayName(t),
    school: t.school,
    subject: t.subject,
    welcome_message: t.welcome_message,
    photo_url: t.photo_path ? urls.get(t.photo_path) ?? null : null,
    is_admin: t.is_admin,
  };
}

// ---------- function ----------
// Teacher endpoint (multi-teacher).
// Public actions: `teachers` (names for the login screen), `register`, `login`.
// Everything else needs a signed session (`x-teacher-token` header) and only ever
// touches the signed-in teacher's own classes, words and submissions.
// Admin-only actions are marked [admin].

const SESSION_HOURS = 8;
const FAIL_WINDOW_MIN = 15;
const MAX_FAILS_PER_IP = 8;
const MAX_FAILS_GLOBAL = 40;
const MAX_TEACHER_PHOTO = 1024 * 1024;

type Sub = Record<string, unknown> & { id: string; photo_path: string | null; audio_path: string };

const LIST_COLS =
  'id, pupil_name, class_name, sentence, who, what_happens, where_text, when_text, status, created_at, reviewed_at, audio_duration_ms, challenge_done, used_word_of_day, share_token, photo_path, audio_path, audio_mime';

const db = () => admin();

// ------------------------------------------------------------ helpers
async function guardAttempts(req: Request) {
  const ip = clientIp(req);
  const since = new Date(Date.now() - FAIL_WINDOW_MIN * 60_000).toISOString();
  const { count: ipCount } = await db()
    .from('login_attempts')
    .select('id', { count: 'exact', head: true })
    .eq('ip', ip)
    .eq('success', false)
    .gte('created_at', since);
  const { count: allCount } = await db()
    .from('login_attempts')
    .select('id', { count: 'exact', head: true })
    .eq('success', false)
    .gte('created_at', since);
  if ((ipCount ?? 0) >= MAX_FAILS_PER_IP || (allCount ?? 0) >= MAX_FAILS_GLOBAL) {
    throw new HttpError(429, `Too many wrong tries. Please wait ${FAIL_WINDOW_MIN} minutes and try again.`);
  }
  return async (success: boolean) => {
    await db().from('login_attempts').insert({ ip, success });
  };
}

function initialPin(): string {
  const p = Deno.env.get('INITIAL_TEACHER_PIN') ?? '';
  if (!PIN_RE.test(p)) throw new HttpError(500, 'INITIAL_TEACHER_PIN is not configured on the server (4–8 digits).');
  return p;
}

function checkPin(pin: string, t: Pick<TeacherRow, 'pin_hash'>): Promise<boolean> {
  if (!PIN_RE.test(pin)) return Promise.resolve(false);
  if (t.pin_hash) return verifyPin(pin, t.pin_hash);
  return Promise.resolve(safeEqual(pin, initialPin())); // recovery: PIN cleared in the database
}

async function issue(t: TeacherRow) {
  const exp = Math.floor(Date.now() / 1000) + SESSION_HOURS * 3600;
  const token = await signSession({ sub: t.id, exp, pv: await pinFingerprint(t.pin_hash) });
  return { token, expires_at: exp * 1000 };
}

async function profile(t: TeacherRow) {
  const urls = await signUrls([t.photo_path]);
  return { ...publicTeacher(t, urls), using_initial_pin: !t.pin_hash };
}

function cleanProfile(body: Record<string, unknown>) {
  const title = str(body.title, 20) || 'Teacher';
  const name = str(body.name, 40);
  if (!name) throw new HttpError(400, 'Please type your name.');
  return {
    title,
    name,
    school: str(body.school, 80) || null,
    subject: str(body.subject, 40) || null,
    welcome_message: str(body.welcome_message, 140) || null,
  };
}

async function nameTaken(title: string, name: string, exceptId?: string) {
  const rows = must(await db().from('teachers').select('id, title, name')) as Pick<TeacherRow, 'id' | 'title' | 'name'>[];
  const want = displayName({ title, name }).toLowerCase();
  return rows.some((r) => r.id !== exceptId && displayName(r).toLowerCase() === want);
}

async function withUrls(rows: Sub[], opts: { photo?: boolean; audio?: boolean }) {
  const urls = await signUrls(rows.flatMap((r) => [opts.photo ? r.photo_path : null, opts.audio ? r.audio_path : null]));
  return rows.map((r) => {
    const { photo_path, audio_path, ...rest } = r;
    return {
      ...rest,
      has_photo: !!photo_path,
      photo_url: photo_path ? urls.get(photo_path) ?? null : null,
      audio_url: opts.audio ? urls.get(audio_path) ?? null : null,
    };
  });
}

async function removeTeacherFiles(teacherId: string) {
  const subs = must(await db().from('submissions').select('photo_path, audio_path').eq('teacher_id', teacherId)) as {
    photo_path: string | null;
    audio_path: string;
  }[];
  const t = must(await db().from('teachers').select('photo_path').eq('id', teacherId).maybeSingle()) as { photo_path: string | null } | null;
  const paths = [...subs.flatMap((s) => [s.photo_path, s.audio_path]), t?.photo_path].filter((p): p is string => !!p);
  for (let i = 0; i < paths.length; i += 100) await db().storage.from(BUCKET).remove(paths.slice(i, i + 100));
}

function decodeDataUrl(dataUrl: string): { bytes: Uint8Array; type: string } {
  const m = /^data:(image\/(?:jpeg|png|webp));base64,([A-Za-z0-9+/=]+)$/.exec(dataUrl);
  if (!m) throw new HttpError(400, 'That file is not a photo.');
  const bin = atob(m[2]);
  if (bin.length > MAX_TEACHER_PHOTO) throw new HttpError(413, 'The photo is too big.');
  return { bytes: Uint8Array.from(bin, (c) => c.charCodeAt(0)), type: m[1] };
}

// ------------------------------------------------------------ handler
serve(async (req) => {
  if (req.method !== 'POST') throw new HttpError(405, 'Use POST.');
  const body = (await req.json().catch(() => ({}))) as Record<string, unknown>;
  const action = str(body.action, 30);

  // ======================= public actions =======================
  if (action === 'teachers') {
    const rows = must(await db().from('teachers').select('*').order('name')) as TeacherRow[];
    const urls = await signUrls(rows.map((r) => r.photo_path));
    return json(req, {
      teachers: rows.map((r) => {
        const p = publicTeacher(r, urls);
        return { id: p.id, display_name: p.display_name, photo_url: p.photo_url, subject: p.subject };
      }),
    });
  }

  if (action === 'register') {
    const record = await guardAttempts(req);
    const settings = must(await db().from('app_settings').select('*').eq('id', 1).single()) as {
      registration_code: string | null;
      photo_required: boolean;
      word_of_day: unknown;
      challenge: unknown;
    };
    const expected = (settings.registration_code || initialPin()).trim().toUpperCase();
    const code = str(body.school_code, 30).toUpperCase();
    if (!code || !safeEqual(code, expected)) {
      await record(false);
      throw new HttpError(401, 'That school code is not right. Ask your school admin.');
    }
    const pin = str(body.pin, 8);
    if (!PIN_RE.test(pin)) throw new HttpError(400, 'Your PIN must be 4 to 8 digits.');
    const p = cleanProfile(body);
    if (await nameTaken(p.title, p.name)) throw new HttpError(409, `“${displayName(p)}” is already registered. Add your surname or initial.`);

    const { count } = await db().from('teachers').select('id', { count: 'exact', head: true });
    const first = (count ?? 0) === 0;
    const teacher = must(
      await db()
        .from('teachers')
        .insert({
          ...p,
          pin_hash: await hashPin(pin),
          is_admin: first,
          photo_required: first ? settings.photo_required : true,
          word_of_day: first ? settings.word_of_day : null,
          challenge: first ? settings.challenge : null,
        })
        .select('*')
        .single(),
    ) as TeacherRow;

    // Every teacher starts with a copy of the school's default word bank.
    const defaults = must(await db().from('word_bank').select('category, text, is_plural, sort_order').is('teacher_id', null)) as {
      category: string;
      text: string;
      is_plural: boolean;
      sort_order: number;
    }[];
    if (defaults.length) must(await db().from('word_bank').insert(defaults.map((w) => ({ ...w, teacher_id: teacher.id }))));

    // The first teacher (the admin) takes over anything created before teachers existed.
    if (first) {
      must(await db().from('classes').update({ teacher_id: teacher.id }).is('teacher_id', null));
      must(await db().from('submissions').update({ teacher_id: teacher.id }).is('teacher_id', null));
    }
    await record(true);
    return json(req, { ...(await issue(teacher)), teacher: await profile(teacher), first });
  }

  if (action === 'login') {
    const record = await guardAttempts(req);
    const id = str(body.teacher_id, 36);
    const pin = str(body.pin, 8);
    const t = UUID_RE.test(id) ? (must(await db().from('teachers').select('*').eq('id', id).maybeSingle()) as TeacherRow | null) : null;
    const ok = !!t && (await checkPin(pin, t));
    await record(ok);
    if (!ok || !t) throw new HttpError(401, 'Wrong PIN. Please try again.');
    await db().from('login_attempts').delete().lt('created_at', new Date(Date.now() - 7 * 86400_000).toISOString());
    return json(req, { ...(await issue(t)), teacher: await profile(t) });
  }

  // ======================= signed-in actions =======================
  const session = await readSession(req.headers.get('x-teacher-token'));
  const me = session && UUID_RE.test(session.sub)
    ? (must(await db().from('teachers').select('*').eq('id', session.sub).maybeSingle()) as TeacherRow | null)
    : null;
  if (!session || !me || session.pv !== (await pinFingerprint(me.pin_hash))) {
    throw new HttpError(401, 'Your teacher session has ended. Please enter your PIN again.');
  }
  const myId = me.id;
  const needAdmin = () => {
    if (!me.is_admin) throw new HttpError(403, 'Only the school admin can do that.');
  };

  switch (action) {
    case 'session':
      return json(req, { ok: true, teacher: await profile(me) });

    // ---------------------------------------------------- submissions (own only)
    case 'stats': {
      const count = async (status?: string) => {
        let q = db().from('submissions').select('id', { count: 'exact', head: true }).eq('teacher_id', me.id);
        if (status) q = q.eq('status', status);
        const { count, error } = await q;
        if (error) throw new HttpError(500, 'Database error.');
        return count ?? 0;
      };
      const [total, pending, approved, rejected] = await Promise.all([count(), count('pending'), count('approved'), count('rejected')]);
      return json(req, { total, pending, approved, rejected });
    }

    case 'list': {
      let q = db().from('submissions').select(LIST_COLS).eq('teacher_id', myId).order('created_at', { ascending: false }).limit(1000);
      const status = str(body.status, 10);
      const cls = str(body.class_name, 40);
      if (['pending', 'approved', 'rejected'].includes(status)) q = q.eq('status', status);
      if (cls) q = q.eq('class_name', cls);
      return json(req, { submissions: await withUrls(must(await q) as unknown as Sub[], {}) });
    }

    case 'get': {
      const row = must(await db().from('submissions').select(LIST_COLS).eq('teacher_id', myId).eq('id', str(body.id, 36)).maybeSingle()) as Sub | null;
      if (!row) throw new HttpError(404, 'Submission not found.');
      return json(req, { submission: (await withUrls([row], { photo: true, audio: true }))[0] });
    }

    case 'set_status': {
      const id = str(body.id, 36);
      const status = str(body.status, 10);
      if (!['pending', 'approved', 'rejected'].includes(status)) throw new HttpError(400, 'Invalid status.');
      const row = must(await db().from('submissions').select('id, share_token').eq('teacher_id', myId).eq('id', id).maybeSingle()) as
        | { id: string; share_token: string | null }
        | null;
      if (!row) throw new HttpError(404, 'Submission not found.');
      // The share token is created once and kept, so a printed QR code keeps working if re-approved.
      const patch: Record<string, unknown> = { status, reviewed_at: new Date().toISOString() };
      if (status === 'approved' && !row.share_token) patch.share_token = randomToken(24);
      must(await db().from('submissions').update(patch).eq('teacher_id', myId).eq('id', id));
      return json(req, { ok: true });
    }

    case 'delete': {
      const id = str(body.id, 36);
      const row = must(await db().from('submissions').select('photo_path, audio_path').eq('teacher_id', myId).eq('id', id).maybeSingle()) as
        | { photo_path: string | null; audio_path: string }
        | null;
      if (!row) return json(req, { ok: true });
      const paths = [row.photo_path, row.audio_path].filter((p): p is string => !!p);
      if (paths.length) await db().storage.from(BUCKET).remove(paths);
      must(await db().from('submissions').delete().eq('teacher_id', myId).eq('id', id));
      return json(req, { ok: true });
    }

    case 'gallery':
    case 'cards': {
      let q = db().from('submissions').select(LIST_COLS).eq('teacher_id', myId).eq('status', 'approved').order('class_name').order('pupil_name');
      const cls = str(body.class_name, 40);
      if (cls) q = q.eq('class_name', cls);
      if (Array.isArray(body.ids) && body.ids.length) q = q.in('id', body.ids.slice(0, 100).map((x: unknown) => str(x, 36)));
      const rows = must(await q) as unknown as Sub[];
      return json(req, { submissions: await withUrls(rows, { photo: true, audio: action === 'gallery' }) });
    }

    // ---------------------------------------------------- my settings
    case 'get_settings': {
      const settings = must(await db().from('app_settings').select('classroom_name, registration_code').eq('id', 1).single()) as {
        classroom_name: string;
        registration_code: string | null;
      };
      const classes = must(await db().from('classes').select('id, name, access_code').eq('teacher_id', myId).order('name'));
      const words = must(await db().from('word_bank').select('id, category, text, is_plural, sort_order').eq('teacher_id', myId).order('sort_order').order('text'));
      const out: Record<string, unknown> = {
        school_name: settings.classroom_name,
        profile: await profile(me),
        photo_required: me.photo_required,
        word_of_day: me.word_of_day,
        challenge: me.challenge,
        classes,
        words,
      };
      if (me.is_admin) {
        const teachers = must(await db().from('teachers').select('*').order('name')) as TeacherRow[];
        const allClasses = must(await db().from('classes').select('teacher_id')) as { teacher_id: string | null }[];
        out.admin = {
          registration_code: settings.registration_code,
          teachers: teachers.map((t) => ({
            id: t.id,
            display_name: displayName(t),
            school: t.school,
            subject: t.subject,
            is_admin: t.is_admin,
            class_count: allClasses.filter((c) => c.teacher_id === t.id).length,
            created_at: t.created_at,
          })),
        };
      }
      return json(req, out);
    }

    case 'update_profile': {
      const p = cleanProfile(body);
      if (await nameTaken(p.title, p.name, me.id)) throw new HttpError(409, `“${displayName(p)}” is already registered.`);
      must(await db().from('teachers').update(p).eq('id', me.id));
      return json(req, { ok: true });
    }

    case 'set_photo': {
      const { bytes, type } = decodeDataUrl(str(body.data_url, 2_000_000));
      const path = `teachers/${me.id}-${randomToken(6)}.${type === 'image/png' ? 'png' : type === 'image/webp' ? 'webp' : 'jpg'}`;
      const up = await db().storage.from(BUCKET).upload(path, bytes, { contentType: type, upsert: true });
      if (up.error) throw new HttpError(500, 'Could not save the photo.');
      if (me.photo_path) await db().storage.from(BUCKET).remove([me.photo_path]);
      must(await db().from('teachers').update({ photo_path: path }).eq('id', me.id));
      return json(req, { ok: true });
    }

    case 'remove_photo': {
      if (me.photo_path) await db().storage.from(BUCKET).remove([me.photo_path]);
      must(await db().from('teachers').update({ photo_path: null }).eq('id', me.id));
      return json(req, { ok: true });
    }

    case 'update_settings': {
      const patch: Record<string, unknown> = {};
      if (typeof body.photo_required === 'boolean') patch.photo_required = body.photo_required;
      if ('word_of_day' in body) {
        const w = body.word_of_day as Record<string, unknown> | null;
        patch.word_of_day =
          w && str(w.word, 30)
            ? { word: str(w.word, 30), meaning: str(w.meaning, 120) || null, date: new Date().toISOString().slice(0, 10) }
            : null;
      }
      if ('challenge' in body) {
        const c = body.challenge as Record<string, unknown> | null;
        const mw = Number(c?.min_words);
        patch.challenge =
          c && str(c.title, 100)
            ? {
                title: str(c.title, 100),
                required_word: str(c.required_word, 30) || null,
                min_words: Number.isFinite(mw) && mw > 0 ? Math.min(30, Math.floor(mw)) : null,
              }
            : null;
      }
      if (Object.keys(patch).length) must(await db().from('teachers').update(patch).eq('id', me.id));
      return json(req, { ok: true });
    }

    case 'class_add':
    case 'class_update': {
      const name = str(body.name, 40);
      const code = str(body.access_code, 20).toUpperCase().replace(/\s/g, '');
      if (!name) throw new HttpError(400, 'Please enter a class name.');
      if (code.length < 4) throw new HttpError(400, 'The access code needs at least 4 letters or numbers.');
      const res =
        action === 'class_add'
          ? await db().from('classes').insert({ name, access_code: code, teacher_id: me.id })
          : await db().from('classes').update({ name, access_code: code }).eq('teacher_id', myId).eq('id', str(body.id, 36));
      if (res.error)
        throw new HttpError(
          res.error.code === '23505' ? 409 : 500,
          res.error.code === '23505' ? 'You already have a class with that name.' : 'Could not save the class.',
        );
      return json(req, { ok: true });
    }

    case 'class_delete': {
      must(await db().from('classes').delete().eq('teacher_id', myId).eq('id', str(body.id, 36)));
      return json(req, { ok: true });
    }

    case 'word_add': {
      const category = str(body.category, 10);
      if (!['who', 'what', 'where', 'when'].includes(category)) throw new HttpError(400, 'Invalid category.');
      const text = str(body.text, 60).replace(/[.!?]+$/, '');
      if (!text) throw new HttpError(400, 'Please type a word or phrase.');
      const { data: last } = await db().from('word_bank').select('sort_order').eq('teacher_id', myId)
        .eq('category', category)
        .order('sort_order', { ascending: false })
        .limit(1);
      const res = await db().from('word_bank').insert({
        category,
        text,
        teacher_id: me.id,
        is_plural: category === 'who' ? !!body.is_plural : false,
        sort_order: ((last?.[0]?.sort_order as number | undefined) ?? 0) + 1,
      });
      if (res.error)
        throw new HttpError(
          res.error.code === '23505' ? 409 : 500,
          res.error.code === '23505' ? 'That word is already in your word bank.' : 'Could not add the word.',
        );
      return json(req, { ok: true });
    }

    case 'word_delete': {
      must(await db().from('word_bank').delete().eq('teacher_id', myId).eq('id', str(body.id, 36)));
      return json(req, { ok: true });
    }

    case 'change_pin': {
      const current = str(body.current_pin, 8);
      const next = str(body.new_pin, 8);
      if (!PIN_RE.test(next)) throw new HttpError(400, 'The new PIN must be 4 to 8 digits.');
      if (!(await checkPin(current, me))) throw new HttpError(401, 'Your current PIN is not right.');
      const hash = await hashPin(next);
      must(await db().from('teachers').update({ pin_hash: hash }).eq('id', me.id));
      return json(req, { ok: true, ...(await issue({ ...me, pin_hash: hash })) });
    }

    // ---------------------------------------------------- [admin] school
    case 'school_update': {
      needAdmin();
      const patch: Record<string, unknown> = { updated_at: new Date().toISOString() };
      if (typeof body.school_name === 'string') {
        const n = str(body.school_name, 60);
        if (!n) throw new HttpError(400, 'School name cannot be empty.');
        patch.classroom_name = n;
      }
      if ('registration_code' in body) {
        const c = str(body.registration_code, 30).toUpperCase().replace(/\s/g, '');
        if (c && c.length < 6) throw new HttpError(400, 'The school code needs at least 6 letters or numbers.');
        patch.registration_code = c || null;
      }
      must(await db().from('app_settings').update(patch).eq('id', 1));
      return json(req, { ok: true });
    }

    case 'teacher_reset_pin': {
      needAdmin();
      const id = str(body.teacher_id, 36);
      const pin = str(body.new_pin, 8);
      if (!PIN_RE.test(pin)) throw new HttpError(400, 'The new PIN must be 4 to 8 digits.');
      must(await db().from('teachers').update({ pin_hash: await hashPin(pin) }).eq('id', id));
      return json(req, { ok: true });
    }

    case 'teacher_set_admin': {
      needAdmin();
      const id = str(body.teacher_id, 36);
      const make = !!body.is_admin;
      if (!make) {
        const { count } = await db().from('teachers').select('id', { count: 'exact', head: true }).eq('is_admin', true);
        if ((count ?? 0) <= 1) throw new HttpError(400, 'The school needs at least one admin.');
      }
      must(await db().from('teachers').update({ is_admin: make }).eq('id', id));
      return json(req, { ok: true });
    }

    case 'teacher_remove': {
      needAdmin();
      const id = str(body.teacher_id, 36);
      if (id === me.id) throw new HttpError(400, 'You cannot remove yourself.');
      if (!UUID_RE.test(id)) throw new HttpError(400, 'Invalid teacher.');
      await removeTeacherFiles(id);
      must(await db().from('teachers').delete().eq('id', id)); // classes, words and submissions are removed with them
      return json(req, { ok: true });
    }

    default:
      throw new HttpError(400, 'Unknown action.');
  }
});
